export const bankingCategories = bankingRows.map(([id, label, description]) => ({ id, label, description }));
const bankingDemoOrder = ['lost_or_stolen_card', 'cash_withdrawal_not_recognised', 'pending_transfer', 'request_refund', 'pin_blocked', 'change_pin', 'card_payment_wrong_exchange_rate', 'verify_my_identity'];
const orderedBankingRows = [
  ...bankingDemoOrder.map(id => bankingRows.find(row => row[0] === id)),
  ...bankingRows.filter(row => !bankingDemoOrder.includes(row[0])),
];
const bankingItems = [0, 1].flatMap(variant => orderedBankingRows.map(([intent, categoryLabel, , first, second], index) => ({
  id: `banking-${String(variant * 77 + index + 1).padStart(3, '0')}`,
  title: `Anfrage ${variant * 77 + index + 1}`,
  text: variant === 0 ? first : second,
  categoryLabel,
  expected: { intent },
})));

